package com.stockshield.entity;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="dead_letter_orders") public class DeadLetterOrder { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false) private Long orderId; @Column(nullable=false,length=2000) private String reason; @Column(nullable=false) private Instant createdAt=Instant.now(); @Column(nullable=false) private boolean reprocessed=false; public DeadLetterOrder(){} public DeadLetterOrder(Long o,String r){orderId=o;reason=r;} public Long getId(){return id;} public Long getOrderId(){return orderId;} public String getReason(){return reason;} public Instant getCreatedAt(){return createdAt;} public boolean isReprocessed(){return reprocessed;} public void setReprocessed(boolean v){reprocessed=v;}}
